import React, { useEffect, useState } from "react";
import { Spinner } from "react-bootstrap";
import "./OrderDetail.css";
import { getMyOrderDetail } from "../../Services/ApiUserService.jsx";
import { useParams } from "react-router-dom";

const fmtDateTime = (iso) => {
    try {
        const d = new Date(iso);
        const date = d.toLocaleDateString("vi-VN", { day: "2-digit", month: "2-digit", year: "numeric" });
        const time = d.toLocaleTimeString("vi-VN", { hour12: false }).replace(/\.\d+$/, "");
        return `${date} ${time}`;
    } catch { return "-"; }
};
const fmtMoneySigned = (n) => {
    const x = Number(n) || 0;
    const sign = x > 0 ? "+" : x < 0 ? "-" : "";
    const abs = Math.abs(x).toLocaleString("vi-VN", { maximumFractionDigits: 0 });
    return `${sign}${abs} đ`;
};

const OrderDetail = () => {
    const { id } = useParams();               // id = order_detail_id
    const detailId = Number(id);
    const [detail, setDetail] = useState(null);
    const [loading, setLoading] = useState(false);
    const [err, setErr] = useState("");

    useEffect(() => {
        if (!id || Number.isNaN(detailId)) return;
        (async () => {
            setLoading(true); setErr("");
            try {
                const data = await getMyOrderDetail(detailId);
                setDetail(data);
            } catch {
                setErr("Không tải được chi tiết giao dịch.");
            } finally {
                setLoading(false);
            }
        })();
    }, [detailId, id]);

    if (!id || Number.isNaN(detailId)) {
        return <div className="alert alert-warning m-3">Thiếu hoặc sai định dạng id chi tiết đơn hàng.</div>;
    }
    if (loading) {
        return (
            <div className="d-flex align-items-center gap-2 p-3">
                <Spinner animation="border" size="sm" />
                <span>Đang tải chi tiết…</span>
            </div>
        );
    }
    if (err) return <div className="alert alert-danger m-3">{err}</div>;
    if (!detail) return null;

    // detail schema:
    // { id, user_id, type, amount, description, order_id, created_at }
    return (
        <div className="container py-4 order-detail">
            <p className="mb-3">
                Chi tiết giao dịch cho đơn hàng <strong>#{detail.order_id}</strong>
            </p>

            <h4 className="fw-bold mb-3">Chi tiết</h4>
            <table className="table table-borderless small">
                <tbody>
                    <tr>
                        <td className="text-secondary">Mã chi tiết</td>
                        <td className="text-end">#{detail.id}</td>
                    </tr>
                    <tr>
                        <td className="text-secondary">Người dùng (user_id)</td>
                        <td className="text-end">{detail.user_id}</td>
                    </tr>
                    <tr>
                        <td className="text-secondary">Loại giao dịch</td>
                        <td className="text-end">{detail.type}</td>
                    </tr>
                    <tr>
                        <td className="text-secondary">Số tiền</td>
                        <td className={`text-end fw-semibold ${detail.amount >= 0 ? "text-success" : "text-danger"}`}>
                            {fmtMoneySigned(detail.amount)}
                        </td>
                    </tr>
                    <tr>
                        <td className="text-secondary">Mô tả</td>
                        <td className="text-end">{detail.description || "-"}</td>
                    </tr>
                    <tr>
                        <td className="text-secondary">Thời gian</td>
                        <td className="text-end">{fmtDateTime(detail.created_at)}</td>
                    </tr>
                </tbody>
            </table>

            {/* Nếu muốn link về danh sách đơn */}
            {/* <div className="mt-3">
        <Link to="/orders" className="btn btn-outline-secondary">← Quay lại đơn hàng</Link>
      </div> */}
        </div>
    );
};

export default OrderDetail;
